"""Builds the A2UI skills' generated files from the catalog (skills/ui-*/).

The catalog is the single source of truth: the SDK generates the Express grammar and every
component's signature from it, and this script cuts that text into small files, each placed in
the skill that needs it. A skill loads only its own files, and only when a reply needs them
(see skills/ui-*/SKILL.md). Nothing of it is in the system prompt.

Skills (one per use case, so a reply loads only what it needs):
- ui-forms:   ask the user for details or a confirmation (form components, input checks)
- ui-blocks:  ready-made live cards (one reference per block)
- ui-display: show results (card/list/table components, VegaChart, media)

Generated per skill: references/*.md, references/rules.md and templates/update.md (copied from
app/a2ui/skill_shared/), Hand-written:
SKILL.md and the other templates.

    PYTHONPATH=. python -m app.a2ui.skill_build          # write the files
    PYTHONPATH=. python -m app.a2ui.skill_build --check  # exit 1 if they are out of date

tests/test_a2ui_skill.py runs the check, so a catalog change without a rebuild fails the tests.
"""

import json
import re
import sys
from pathlib import Path

from app.a2ui.catalog import CATALOGS_DIR, INSTRUCTIONS, PROMPT_SNIPPET

SKILLS_DIR = Path(__file__).resolve().parents[2] / "skills"
SHARED = Path(__file__).resolve().parent / "skill_shared"

HEAD = "<!-- Generated by app/a2ui/skill_build.py from the catalog. Do not edit. -->\n"

SIGNATURES = "## Positional Component Signatures"
FUNCTIONS = "## Positional Function Signatures"
CATALOG_INSTRUCTIONS = "## Catalog Instructions"

FORM_COMPONENTS = ["Text", "Row", "Column", "Card", "Divider", "Button",
                   "TextField", "CheckBox", "ChoicePicker", "Slider", "DateTimeInput"]
DISPLAY_COMPONENTS = ["Text", "Image", "Icon", "Row", "Column", "List", "Card", "Tabs", "Divider", "Button"]
MEDIA_COMPONENTS = ["Video", "AudioPlayer", "Modal"]

UI_SKILLS = ("ui-forms", "ui-blocks", "ui-display")


def _section(start: str, end: str | None) -> str:
    i = PROMPT_SNIPPET.index(start)
    j = PROMPT_SNIPPET.index(end, i) if end else len(PROMPT_SNIPPET)
    return PROMPT_SNIPPET[i:j].strip()


def _signatures() -> tuple[str, dict[str, str]]:
    """The signatures section's intro, and each component's signature block by name."""
    body = _section(SIGNATURES, FUNCTIONS)
    intro, *items = re.split(r"\n(?=• )", body)
    by_name = {re.match(r"• (\w+)\(", item).group(1): item.strip() for item in items}
    return intro.removeprefix(SIGNATURES).strip(), by_name


def _components_file(title: str, names: list[str], intro: str, sigs: dict[str, str]) -> str:
    body = "\n\n".join(sigs[n] for n in sorted(names))
    return f"# {title}\n\n{', '.join(names)}.\n\n{intro}\n\n{body}\n"


def build() -> dict[str, str]:
    """{path relative to skills/: content} for every generated file."""
    intro, sigs = _signatures()
    grammar_text = PROMPT_SNIPPET[: PROMPT_SNIPPET.index(SIGNATURES)].strip()
    grammar = f"# A2UI Express: output contract and grammar\n\n{grammar_text}\n"
    functions_text = _section(FUNCTIONS, CATALOG_INSTRUCTIONS).removeprefix(FUNCTIONS).strip()
    functions = (
        "# Functions: input checks (?required, ?email, ?regex, ...) and formatting\n\n"
        f"{functions_text}\n"
    )
    rules = (SHARED / "rules.md").read_text(encoding="utf-8")
    update = (SHARED / "update.md").read_text(encoding="utf-8")

    files: dict[str, str] = {}
    for skill in UI_SKILLS:
        files[f"{skill}/references/grammar.md"] = grammar
        files[f"{skill}/references/rules.md"] = rules
        files[f"{skill}/templates/update.md"] = update

    files["ui-forms/references/components.md"] = _components_file(
        "Form components", FORM_COMPONENTS, intro, sigs)
    files["ui-forms/references/functions.md"] = functions

    files["ui-display/references/components.md"] = _components_file(
        "Display components", DISPLAY_COMPONENTS, intro, sigs)
    files["ui-display/references/components-media.md"] = _components_file(
        "Media and modal components", MEDIA_COMPONENTS,
        "Modal shows a trigger (usually a Button) and opens `content` in a dialog when it is pressed."
        " Both children must be defined as components like any other.", sigs)
    files["ui-display/references/functions.md"] = functions
    files["ui-display/references/chart.md"] = (
        f"# VegaChart: charts, graphs and live formulas\n\n{sigs['VegaChart']}\n\n{INSTRUCTIONS}\n")

    for path in sorted((CATALOGS_DIR / "blocks").glob("*.json")):
        doc = json.loads(path.read_text(encoding="utf-8"))
        names = list(doc["components"])
        body = "\n\n".join(sigs[n] for n in names)
        files[f"ui-blocks/references/block-{path.stem}.md"] = (
            f"# {', '.join(names)} (chat block)\n\n{body}\n\n{doc['guide']}\n")

    # Row data from a file or tool result is charted by DataChart; ui-display carries its signature
    # too, because that is where a chart request lands first.
    files["ui-display/references/block-datachart.md"] = files["ui-blocks/references/block-datachart.md"]

    return {p: HEAD + t for p, t in files.items()}


def _generated_on_disk() -> set[str]:
    """Files under each UI skill that this script owns (references/, update.md)."""
    out: set[str] = set()
    for skill in UI_SKILLS:
        root = SKILLS_DIR / skill
        for sub in ("references", "scripts"):
            if (root / sub).is_dir():
                out |= {f"{skill}/{sub}/{p.name}" for p in (root / sub).iterdir() if p.is_file()}
        if (root / "templates" / "update.md").is_file():
            out.add(f"{skill}/templates/update.md")
    return out


def stale() -> list[str]:
    """Generated files that differ from what the catalog gives, are missing, or shouldn't exist."""
    want = build()
    out = [p for p, text in want.items()
           if not (SKILLS_DIR / p).is_file() or (SKILLS_DIR / p).read_text(encoding="utf-8") != text]
    return out + sorted(_generated_on_disk() - set(want))


def write() -> None:
    want = build()
    for p in _generated_on_disk() - set(want):
        (SKILLS_DIR / p).unlink()
    for p, text in want.items():
        target = SKILLS_DIR / p
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, newline="\n", encoding="utf-8")


if __name__ == "__main__":
    if "--check" in sys.argv:
        bad = stale()
        if bad:
            print("out of date:", ", ".join(bad), "- run: PYTHONPATH=. python -m app.a2ui.skill_build")
            sys.exit(1)
        print("skills/ui-*/ generated files are up to date")
    else:
        write()
        for skill in UI_SKILLS:
            sizes = {p.name: len(p.read_text(encoding="utf-8"))
                     for p in sorted((SKILLS_DIR / skill / "references").glob("*.md"))}
            print(skill, sizes)
